import { inject, type InjectionKey } from 'vue';
import type { ToggleSize, ToggleVariant } from '../toggle/Toggle.vue';

export type ToggleGroupStyleContextValue = {
  size: () => ToggleSize;
  variant: () => ToggleVariant;
};

const defaultToggleGroupStyleContext: ToggleGroupStyleContextValue = {
  size: () => 'md',
  variant: () => 'default',
};

export const ToggleGroupStyleContextKey: InjectionKey<ToggleGroupStyleContextValue> =
  Symbol('ToggleGroupStyleContext');

export const useToggleGroupStyleContext = () =>
  inject(ToggleGroupStyleContextKey, defaultToggleGroupStyleContext);

import { cva } from 'class-variance-authority';

export const toggleGroupRootVariants = cva(
  'group/toggle-group inline-flex max-w-full items-center gap-px overflow-x-auto overscroll-x-contain rounded-lg border border-border bg-muted p-0.5 text-foreground [scrollbar-width:none] data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch [&::-webkit-scrollbar]:hidden',
  {
    variants: {
      variant: {
        default: '',
        outline: 'bg-background',
        ghost: 'border-transparent bg-transparent p-0',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  },
);

import {
  ToggleGroupContext,
  useToggleGroup,
  useToggleGroupContext,
} from '@ark-ui/vue/toggle-group';
import ToggleGroup from './ToggleGroup.vue';
import ToggleGroupItem from './ToggleGroupItem.vue';
import ToggleGroupRootProvider from './ToggleGroupRootProvider.vue';

export {
  ToggleGroup,
  ToggleGroupContext,
  ToggleGroupItem,
  ToggleGroupRootProvider,
  useToggleGroup,
  useToggleGroupContext,
};

export type {
  ToggleGroupContextProps,
  ToggleGroupItemBaseProps,
  ToggleGroupRootBaseProps,
  ToggleGroupRootEmits,
  ToggleGroupRootProviderBaseProps,
  ToggleGroupValueChangeDetails,
  UseToggleGroupContext,
  UseToggleGroupProps,
  UseToggleGroupReturn,
} from '@ark-ui/vue/toggle-group';

export type { ToggleGroupItemProps } from './ToggleGroupItem.vue';
export type { ToggleGroupRootProps } from './ToggleGroup.vue';
export type { ToggleGroupRootProviderProps } from './ToggleGroupRootProvider.vue';
export type { ToggleSize, ToggleVariant } from '../toggle/Toggle.vue';
